import numpy as np
from scipy.optimize import minimize
x=np.array([0,1,-1,0,0,2,-2,0,0,1.],float); y=np.array([0,0,0,1,-1,0,0,2,-2,1.],float)
obs=np.array([0.07104045916557955,.5393586782571145,-.18055915582070148,.42142164682482364,-1.6052614392042708,-.38246713057260806,-1.618738394243865,-.2727492651071234,-1.5334683661704505,2.652758337287376])
loc_sd=1.5; lognoise_mu=np.log(.4);lognoise_sd=.6
common_prior=lambda u: -.5*((u[0]/loc_sd)**2+(u[1]/loc_sd)**2)-np.log(2*np.pi*loc_sd**2)

def build(name):
 if name=='invsq_c1':
  names=['sx','sy','logA','logeps','logsig']; mus=[0,0,0,np.log(.1),lognoise_mu]; sds=[loc_sd,loc_sd,1.5,1,.6]
  def mean(u): return u[2]-np.log((x-u[0])**2+(y-u[1])**2+np.exp(u[3]))
  init=[.9,.93,.54,np.log(.106),np.log(.43)]
 elif name=='invsq_c':
  names=['sx','sy','logA','logeps','logc','logsig']; mus=[0,0,0,np.log(.1),0,lognoise_mu]; sds=[loc_sd,loc_sd,1.5,1,.5,.6]
  def mean(u): return u[2]-np.exp(u[4])*np.log((x-u[0])**2+(y-u[1])**2+np.exp(u[3]))
  init=[.82,.87,.3,np.log(.02),np.log(.84),np.log(.46)]
 elif name=='logr':
  names=['sx','sy','b','logc','logeps','logsig']; mus=[0,0,0,np.log(2),np.log(.1),lognoise_mu]; sds=[loc_sd,loc_sd,2,.7,1,.6]
  def mean(u): return u[2]-np.exp(u[3])*np.log(np.sqrt((x-u[0])**2+(y-u[1])**2)+np.exp(u[4]))
  init=[.82,.88,.38,np.log(1.75),np.log(.056),np.log(.45)]
 elif name=='power':
  names=['sx','sy','b','logc','logp','logsig']; mus=[0,0,0,np.log(2),np.log(.5),lognoise_mu]; sds=[loc_sd,loc_sd,2,.7,.7,.6]
  def mean(u): return u[2]-np.exp(u[3])*np.sqrt((x-u[0])**2+(y-u[1])**2)**np.exp(u[4])
  init=[.83,.89,2.66,np.log(2.3),np.log(.54),np.log(.45)]
 elif name=='gauss_add':
  names=['sx','sy','b','logA','logell','logsig']; mus=[0,0,-1,np.log(3),0,lognoise_mu]; sds=[loc_sd,loc_sd,2,1,1,.6]
  def mean(u): return u[2]+np.exp(u[3])*np.exp(-((x-u[0])**2+(y-u[1])**2)/(2*np.exp(2*u[4])))
  init=[.97,.99,-1.34,np.log(3.83),np.log(.88),np.log(.49)]
 elif name=='gauss_log':
  names=['sx','sy','logI0','logA','logell','logsig']; mus=[0,0,np.log(.2),np.log(10),np.log(.8),lognoise_mu]; sds=[loc_sd,loc_sd,1.5,1.5,1,.6]
  def mean(u): return np.log(np.exp(u[2])+np.exp(u[3])*np.exp(-((x-u[0])**2+(y-u[1])**2)/(2*np.exp(2*u[4]))))
  init=[1.02,1.03,np.log(.3),np.log(10.3),np.log(.56),np.log(.52)]
 def logpost(u):
  mu=mean(u);sig=np.exp(u[-1]);r=obs-mu
  ll=-.5*np.sum((r/sig)**2)-len(obs)*u[-1]-.5*len(obs)*np.log(2*np.pi)
  lp=common_prior(u)
  for j in range(len(u)):
   if j<2:continue
   lp+=-.5*((u[j]-mus[j])/sds[j])**2-np.log(np.sqrt(2*np.pi)*sds[j])
  return ll+lp
 return names,mus,sds,init,mean,logpost

results={}
for name in ['invsq_c1','invsq_c','logr','power','gauss_add','gauss_log']:
 names,mus,sds,init,mean,logpost=build(name)
 best=None
 for j in range(3):
  st=np.array(init,float)+np.r_[np.zeros(2),np.random.default_rng(j).normal(0,.1,len(init)-2)]
  r=minimize(lambda u:-logpost(u),st,method='Nelder-Mead',options={'maxiter':100000,'xatol':1e-9,'fatol':1e-8,'maxfev':100000})
  if best is None or r.fun<best.fun:best=r
 u=best.x; h=1e-4;n=len(u);H=np.zeros((n,n))
 for i in range(n):
