   ei=np.zeros(n);ej=np.zeros(n);ei[i]=h;ej[j]=h
   H[i,j]=H[j,i]=(logpost(u+ei+ej)-logpost(u+ei-ej)-logpost(u-ei+ej)+logpost(u-ei-ej))/(4*h*h)
 sign,ld=np.linalg.slogdet(-H)
 logZ=logpost(u)+ld+.5*n*np.log(2*np.pi)
 results[name]=logZ
 print(name,'MAP',np.round(u,5),'lp',round(logpost(u),3),'logZ',round(logZ,3),'sign',sign)
 # save
 np.save('/tmp/opencode/'+name+'.npy',u)
mx=max(results.values());w={k:np.exp(v-mx) for k,v in results.items()};Z=sum(w.values());w={k:v/Z for k,v in w.items()}
print('\nweights',w)
